// ---- film (pop/rovers/render_film.py): ±10,7 s, 24 fps; per segment één beweging, overgangen gemengd (P.meng) ----
TV_pop_eco_rovers.film = (ctx, f) => { const fps = 24, t = f / fps, W = 1920, H = 1080, gy = 860;
  const seg = [[0, 1.3, 'vos', 'lopen', 'vos · stap'], [1.3, 2.6, 'vos', 'draven', 'vos · draf'], [2.6, 3.8, 'vos', 'sluipen', 'vos · sluipen'], [3.8, 5.1, 'vos', 'muizensprong', 'vos · muizensprong'], [5.1, 5.9, 'vos', 'eten', 'vos · eten'],
    [5.9, 7.2, 'lynx', 'lopen', 'lynx · stap'], [7.2, 8.2, 'lynx', 'sluipen', 'lynx · sluipen'], [8.2, 9.4, 'lynx', 'besprong', 'lynx · besprong'], [9.4, 10.7, 'lynx', 'sprinten', 'lynx · sprint (bounding)']];
  const S = seg.find(z => t >= z[0] && t < z[1]) || seg[seg.length - 1]; const [t0, t1, n, h, label] = S; const ts = t - t0, dur = t1 - t0;
  const P = ECO_ROVER[n], px = n === 'vos' ? 8.6 : 6.8; const freq = { vos: { lopen: 1.6, draven: 2.6, sluipen: 0.8 }, lynx: { lopen: 1.2, sluipen: 0.7, sprinten: 2.3 } }[n];
  const sm = (u) => { u = Math.max(0, Math.min(1, u)); return u * u * (3 - 2 * u); };
  let st, snel = 0, x = 960, muisX = null;
  if (P.SPRONG[h]) { const u = Math.min(1, ts / (dur - 0.05)); x = n === 'vos' ? 470 : 380;
    st = P.stand({ houding: h, t: u }); const prev = seg[seg.indexOf(S) - 1]; // instap: eerste 0,2 s mengen vanuit de vorige gang (zelfde plek)
    if (ts < 0.2) st = P.meng(P.stand({ houding: prev[3], t: (prev[1] - prev[0]) * freq[prev[3]] }), st, sm(ts / 0.2));
    if (n === 'vos') muisX = x + (P.stand({ houding: h, t: 1 }).voeten.V.teen[0] - P.D.anker + 2) * px; }
  else if (h === 'eten') { const e = P.SPRONG.muizensprong.S, sp = P.stand({ houding: 'muizensprong', t: 1 }), et = P.stand({ houding: 'eten' }); x = 470;
    const et2 = Object.assign({}, et, { R: [et.R[0] + 92, et.R[1]] }); st = P.meng(sp, et2, sm(ts / 0.4)); muisX = x + (sp.voeten.V.teen[0] - P.D.anker + 2) * px; }
  else { const prev = seg[seg.indexOf(S) - 1]; snel = P.SNELHEID[h] * freq[h]; st = P.stand({ houding: h, t: ts * freq[h] }); if (h === 'sluipen') x = n === 'vos' ? 470 : 380; // sluipen eindigt waar de sprong begint
    if (prev && prev[2] === n && !P.SPRONG[prev[3]] && ts < 0.25) { st = P.meng(P.stand({ houding: prev[3], t: (prev[1] - prev[0]) * freq[prev[3]] }), st, sm(ts / 0.25)); } }
  // achtergrond: rustig veld (vos) / sneeuw (lynx); schuift mee met de loopsnelheid. Geen korrel.
  const sneeuw = n === 'lynx'; const scroll = ((snel * ts * px) % 600 + 600) % 600, scroll2 = ((snel * ts * px * 0.35) % 900 + 900) % 900;
  ctx.fillStyle = sneeuw ? '#2A3A56' : '#1E2A47'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = sneeuw ? '#34496A' : '#243656'; ctx.fillRect(0, gy - 260, W, 260);
  ctx.fillStyle = sneeuw ? '#3C5478' : '#2B3E5E'; for (let i = -1; i < 4; i++) { const xx = i * 900 - scroll2; ctx.beginPath(); ctx.ellipse(xx + 300, gy - 240, 260, 60, 0, Math.PI, 0); ctx.fill(); }
  ctx.fillStyle = sneeuw ? '#C9D3DE' : '#3B5240'; ctx.fillRect(0, gy, W, H - gy);
  ctx.fillStyle = sneeuw ? '#B7C3D0' : '#2F4434'; for (let i = -1; i < 5; i++) { const xx = i * 600 - scroll; for (let k = 0; k < 6; k++) { ctx.beginPath(); ctx.ellipse(xx + k * 97 + (k % 2) * 30, gy + 30 + (k * 37) % 120, 46, 7, 0, 0, 6.283); ctx.fill(); } }
  ctx.strokeStyle = sneeuw ? '#DCE3EA' : '#4C6650'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke();
  if (muisX != null && typeof muis === 'function' && (h === 'eten' || ts > 0.1)) muis(ctx, muisX, gy, px, { houding: 'staan', kijk: -1 });
  P.teken(ctx, x, gy, px, { stand: st });
  ctx.fillStyle = '#E8E2D6'; ctx.font = '600 40px "Source Sans 3", sans-serif'; ctx.textAlign = 'left'; ctx.fillText(label, 70, 90); };
